$script:MIOS_WSL2_FIREWALL = if ($env:MIOS_WSL2_FIREWALL) { $env:MIOS_WSL2_FIREWALL } else { 'false' }
$script:MIOS_WSL2_GUI_APPLICATIONS = if ($env:MIOS_WSL2_GUI_APPLICATIONS) { $env:MIOS_WSL2_GUI_APPLICATIONS } else { 'true' }
$script:MIOS_WSL2_LOCALHOST_FORWARDING = if ($env:MIOS_WSL2_LOCALHOST_FORWARDING) { $env:MIOS_WSL2_LOCALHOST_FORWARDING } else { 'true' }
$script:MIOS_WSL2_NETWORKING_MODE = if ($env:MIOS_WSL2_NETWORKING_MODE) { $env:MIOS_WSL2_NETWORKING_MODE } else { 'NAT' }
$script:MIOS_WSLBOOT_DONE = if ($env:MIOS_WSLBOOT_DONE) { $env:MIOS_WSLBOOT_DONE } else { "$($script:MIOS_PATHS_WSL_FIRSTBOOT_DONE)" }
$script:MIOS_WSLG_GDK_BACKEND = if ($env:MIOS_WSLG_GDK_BACKEND) { $env:MIOS_WSLG_GDK_BACKEND } else { "$($script:MIOS_WSL2_DESKTOP_COMPAT_GDK_BACKEND)" }
$script:MIOS_WSLG_MOZ_WAYLAND = if ($env:MIOS_WSLG_MOZ_WAYLAND) { $env:MIOS_WSLG_MOZ_WAYLAND } else { "$($script:MIOS_WSL2_DESKTOP_COMPAT_MOZ_WAYLAND)" }
$script:MIOS_WSLG_QT_PLATFORM = if ($env:MIOS_WSLG_QT_PLATFORM) { $env:MIOS_WSLG_QT_PLATFORM } else { "$($script:MIOS_WSL2_DESKTOP_COMPAT_QT_PLATFORM)" }
$script:MIOS_WSL_DISTRO = if ($env:MIOS_WSL_DISTRO) { $env:MIOS_WSL_DISTRO } else { 'MiOS' }
$script:MIOS_XDG_CACHE_LOCAL_PATH = if ($env:MIOS_XDG_CACHE_LOCAL_PATH) { $env:MIOS_XDG_CACHE_LOCAL_PATH } else { "$($script:MIOS_STORAGE_CEPHFS_XDG_CACHE_HOME_OVERRIDE)" }

# ── IMAGE DEFAULT (asserted by the image-parity drift check) ─────────
$defaultImageName = 'ghcr.io/mios-dev/mios'

# ── WINDOWS HOST PATHS (resolved from the live environment) ──────────
$script:MIOS_WIN_APPDATA_DIR = if ($env:APPDATA)     { $env:APPDATA }     else { "$HOME/AppData/Roaming" }
$script:MIOS_WIN_DOCS_DIR    = if ($env:USERPROFILE) { "$env:USERPROFILE/Documents" } else { "$HOME/Documents" }
$script:MIOS_WIN_REPO_DIR    = if ($env:MIOS_WIN_REPO_DIR) { $env:MIOS_WIN_REPO_DIR } else { "$HOME/MiOS" }
